package com.raceforge.backend.permission.entity;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.SequenceGenerator;
import jakarta.persistence.Table;

// Maps to table Role: role_id INT generated by seq_Role, role_name VARCHAR(50) UNIQUE.
@Entity(name = "PermissionRole")
@Table(name = "[Role]")
public class Role {

  @Id
  @GeneratedValue(strategy = GenerationType.SEQUENCE, generator = "permission_role_id_seq")
  @SequenceGenerator(name = "permission_role_id_seq", sequenceName = "seq_Role", allocationSize = 1)
  @Column(name = "role_id")
  private Integer roleId;

  @Column(name = "role_name", nullable = false, unique = true, length = 50)
  private String roleName;

  public Role() {
  }

  public Role(String roleName) {
      this.roleName = roleName;
  }

  public Integer getRoleId() {
      return roleId;
  }

  public void setRoleId(Integer roleId) {
      this.roleId = roleId;
  }

  public String getRoleName() {
      return roleName;
  }

  public void setRoleName(String roleName) {
      this.roleName = roleName;
  }
}
